 @Test void repeatedResumesInvalidateOnlyPreviousClosure(){UUID e=event();for(int i=0;i<3;i++){var end=command(e,2L*i,"ENDED",null);assertEquals((long)i+1,end.transition().closureRevision());var r=command(e,2L*i+1,"RESUMED",null);assertEquals((long)i+1,r.transition().invalidatedClosureRevision());}assertEquals(6,detail(e).version());assertEquals(3,detail(e).lifecycle().closureRevision());assertNull(detail(e).lifecycle().currentClosureRevision());assertEquals(3,lifecycle.periods(admin.principal(),e,0,50).items().size());}
 @Test void lifecyclePagingIsStableByStoredSequenceAndNumber(){UUID e=event();command(e,0,"STARTED",null);command(e,1,"ENDED",null);command(e,2,"RESUMED",null);var all=lifecycle.history(admin.principal(),e,0,50).items();assertEquals(all.getFirst(),lifecycle.history(admin.principal(),e,0,1).items().getFirst());assertEquals(all.get(1),lifecycle.history(admin.principal(),e,1,1).items().getFirst());assertTrue(lifecycle.periods(admin.principal(),e,0,1).hasMore());assertEquals(2,lifecycle.periods(admin.principal(),e,0,1).items().getFirst().number());}
 @Test void registrationOverridesAndCompositionSurviveResume(){var a=actor();UUID e=event(),c=crew(a);var r=register(a,e,c);command(e,0,"STARTED",null);assertFalse(registrations.status(a.principal(),e).canRegister());registrations.settings(admin.principal(),e,1,null,null,"OPEN");assertTrue(registrations.status(a.principal(),e).canRegister());command(e,2,"ENDED",null);assertFalse(registrations.detail(a.principal(),e,r.id()).canEditMembers());command(e,3,"RESUMED",null);assertTrue(registrations.status(a.principal(),e).canRegister());assertTrue(registrations.detail(a.principal(),e,r.id()).canEditMembers());registrations.settings(admin.principal(),e,4,null,null,"AUTO");assertFalse(registrations.status(a.principal(),e).canRegister());}
