 @Test void immutableHistoryAndStateWithoutTransitionAreRejected(){UUID e=event();assertThrows(org.springframework.dao.DataAccessException.class,()->tx().executeWithoutResult(s->jdbc.update("UPDATE race_event SET status='ENDED',last_ended_at=now(),closure_revision=1,current_closure_revision=1 WHERE id=?",e)));command(e,0,"ENDED",null);assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE race_event_lifecycle_history SET cause='END_AT' WHERE race_event_id=?",e));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("DELETE FROM race_event_lifecycle_history WHERE race_event_id=?",e));}
