 @Test void upgradeV26ToV27PreservesDataWithoutInventingLifecycle(){String schema="it_lifecycle_upgrade_"+UUID.randomUUID().toString().replace("-","");UUID t=UUID.randomUUID(),e=UUID.randomUUID();try{org.flywaydb.core.Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("26").load().migrate();jdbc.update("INSERT INTO "+schema+".race_template(id,name,skip_penalty_points,status,version,created_at,updated_at) VALUES (?,'Source',0,'READY',7,now(),now())",t);jdbc.update("INSERT INTO "+schema+".race_event(id,source_template_id,source_template_version,source_template_name,name,skip_penalty_points,version,created_at,updated_at) VALUES (?,?,7,'Source','Preserved',-5,3,now(),now())",e,t);org.flywaydb.core.Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("27").load().migrate();assertEquals(3,count("SELECT version FROM "+schema+".race_event WHERE id=?",e));assertEquals("PLANNED",jdbc.queryForObject("SELECT status FROM "+schema+".race_event WHERE id=?",String.class,e));assertEquals(0,count("SELECT count(*) FROM "+schema+".race_event_lifecycle_history"));assertEquals(0,count("SELECT count(*) FROM "+schema+".race_event_running_period"));}finally{assertTrue(schema.matches("it_lifecycle_upgrade_[0-9a-f]{32}"));jdbc.execute("DROP SCHEMA IF EXISTS "+schema+" CASCADE");}}
 @Test void failedBusinessWriteCommitsDueStartButTechnicalAuditFailureRollsItBack(){UUID e=event();scheduled(e,clock.instant(),null);assertEquals("RACE_EVENT_VERSION_CONFLICT",failure(()->registrations.settings(admin.principal(),e,0,null,null,"OPEN")));assertEquals(1,detail(e).version());assertEquals("RUNNING",detail(e).lifecycle().persistedStatus());UUID second=event();scheduled(second,clock.instant(),null);doThrow(new IllegalStateException("Injected")).when(audit).appendRaceLifecycle(any(),any(),isNull(),eq(Event.RACE_EVENT_STARTED),eq(second),any(),anyLong());assertThrows(RuntimeException.class,()->registrations.settings(admin.principal(),second,0,null,null,"OPEN"));assertEquals("PLANNED",detail(second).lifecycle().persistedStatus());assertEquals(0,detail(second).version());assertEquals(0,count("SELECT count(*) FROM race_event_lifecycle_history WHERE race_event_id=?",second));}
