 @Test void ownCrossEventListIncludesAllStatesAndStablePages(){
  Actor owner=actor(),other=actor();UUID c1=crew(owner),c2=crew(owner),foreign=crew(other);
  UUID future=event(),later=event(),running=event(),ended=event(),undated=event();
  var a=register(owner,future,c1);var b=register(owner,future,c2);var l=register(owner,later,c1);var r=register(owner,running,c1);var e=register(owner,ended,c1);var u=register(owner,undated,c1);register(other,future,foreign);
  Instant at=clock.instant();scheduled(future,at.plusSeconds(10),at.plusSeconds(100));scheduled(later,at.plusSeconds(20),at.plusSeconds(200));scheduled(running,at.minusSeconds(10),at.plusSeconds(100));scheduled(ended,at.minusSeconds(100),at);scheduled(undated,null,null);
  jdbc.update("UPDATE race_event SET registration_override='CLOSED' WHERE id=?",future);
  var expected=new ArrayList<UUID>();expected.addAll(java.util.stream.Stream.of(a.id(),b.id()).sorted(Comparator.comparing(UUID::toString)).toList());expected.addAll(List.of(l.id(),u.id(),r.id(),e.id()));
  var all=registrations.own(owner.principal(),0,100);assertEquals(expected,all.items().stream().map(RegistrationService.OwnView::id).toList());assertEquals(List.of("PLANNED","PLANNED","PLANNED","PLANNED","RUNNING","ENDED"),all.items().stream().map(RegistrationService.OwnView::raceEventStatus).toList());
  var paged=new ArrayList<UUID>();for(int page=0;page<3;page++){var result=registrations.own(owner.principal(),page,2);assertEquals(page<2,result.hasMore());paged.addAll(result.items().stream().map(RegistrationService.OwnView::id).toList());}assertEquals(expected,paged);assertTrue(registrations.own(owner.principal(),3,2).items().isEmpty());
  var first=all.items().stream().filter(x->x.id().equals(a.id())).findFirst().orElseThrow();assertEquals(future,first.raceEventId());assertEquals(c1,first.crewId());assertEquals(at.plusSeconds(10),first.scheduledStartAt());assertEquals(0,first.version());
 }
